"use strict";(self.webpackChunkleia_docs=self.webpackChunkleia_docs||[]).push([[2585],{8878:e=>{e.exports=JSON.parse('{"tag":{"label":"tutorial","permalink":"/pr-preview/pr-16/docs/next/tags/tutorial","allTagsPath":"/pr-preview/pr-16/docs/next/tags","count":8,"items":[{"id":"tutorials/create-from-scratch","title":"A LEIA by hand, without the assistant","description":"The admin role. This path writes a behaviour, which instructors cannot create, and it relies on the Components picker of the design screen, which only administrators see. Advanced accounts get a behaviour of their own through the AI assistant and then edit it by hand.","permalink":"/pr-preview/pr-16/docs/next/tutorials/create-from-scratch"},{"id":"teachers/designer/create-leia","title":"Create a LEIA with the AI assistant","description":"The advanced and admin roles. An instructor can follow every step but Finish LEIA will be refused, because the assistant creates a new behaviour and instructors cannot create behaviours. Instructors should use the quick start instead.","permalink":"/pr-preview/pr-16/docs/next/teachers/designer/create-leia"},{"id":"tutorials/create-leia/index","title":"Quick start, your first LEIA in ten minutes","description":"Every role, including instructor. This path reuses the behaviour of an existing LEIA, so it never creates a behaviour.","permalink":"/pr-preview/pr-16/docs/next/tutorials/create-leia/"},{"id":"tutorials/conversational-game","title":"Scenario, a conversational game","description":"If you want a new exercise similar to one that already exists, start from a featured LEIA with Design from this. The tutorial Your own LEIA from a featured one shows every step.","permalink":"/pr-preview/pr-16/docs/next/tutorials/conversational-game"},{"id":"tutorials/multi-leia-simulation","title":"Scenario, a group simulation with several LEIAs","description":"If you want a new exercise similar to one that already exists, start from a featured LEIA with Design from this. The tutorial Your own LEIA from a featured one shows every step.","permalink":"/pr-preview/pr-16/docs/next/tutorials/multi-leia-simulation"},{"id":"tutorials/programming-exercise","title":"Scenario, a programming exercise with the code editor","description":"If you want a new exercise similar to one that already exists, start from a featured LEIA with Design from this. The tutorial Your own LEIA from a featured one shows every step.","permalink":"/pr-preview/pr-16/docs/next/tutorials/programming-exercise"},{"id":"tutorials/requirements-elicitation","title":"Scenario, a requirements elicitation interview","description":"If you want a new exercise similar to one that already exists, start from a featured LEIA with Design from this. The tutorial Your own LEIA from a featured one shows every step.","permalink":"/pr-preview/pr-16/docs/next/tutorials/requirements-elicitation"},{"id":"tutorials/create-from-featured","title":"Your own LEIA from a featured one","description":"Every role, including instructor. You reuse the behaviour of the featured LEIA and only create a persona and a problem, so no behaviour is created.","permalink":"/pr-preview/pr-16/docs/next/tutorials/create-from-featured"}],"unlisted":false}}')}}]);